package com.hoteluq.model;
import com.hoteluq.model.enums.ReservationStatus;import com.hoteluq.pattern.behavioral.state.*;import java.time.*;import java.util.*;
public class Reservation {private final String id=UUID.randomUUID().toString();private final User customer;private final Room room;private final LocalDate checkIn,checkOut;private final List<AdditionalService> services;private final double total;private ReservationState state=new PendingState();private boolean refunded;
 public Reservation(User c,Room r,LocalDate in,LocalDate out,List<AdditionalService>s,double total){customer=Objects.requireNonNull(c);room=Objects.requireNonNull(r);if(in==null||out==null||!out.isAfter(in))throw new IllegalArgumentException("La salida debe ser posterior a la entrada");checkIn=in;checkOut=out;services=new ArrayList<>(s);this.total=total;}
 public String getId(){return id;}public User getCustomer(){return customer;}public Room getRoom(){return room;}public LocalDate getCheckIn(){return checkIn;}public LocalDate getCheckOut(){return checkOut;}public List<AdditionalService> getServices(){return List.copyOf(services);}public double getTotal(){return total;}public ReservationStatus getStatus(){return state.status();}public void confirm(){state.confirm(this);}public void cancel(){state.cancel(this);}public void setState(ReservationState s){state=s;}public boolean isRefunded(){return refunded;}public void markRefunded(){if(refunded)throw new IllegalStateException("Pago ya reembolsado");refunded=true;}public long nights(){return java.time.temporal.ChronoUnit.DAYS.between(checkIn,checkOut);}}
